const MODO = "simulacion";
const CALENDARIO = "CONFIGURAR_ID_CALENDARIO";
const SECRET = "REEMPLAZAR_EN_N8N";
const URL_PUBLICACION = "https://ejemplo.invalid/api/contrata/disponibilidad.php";
const CUENTA = "info@sobtree.com";
function idOk(id) {
  if (!id || id === "primary") return false;
  if (/@gmail\.com$/i.test(id)) return false;
  return true;
}
if (MODO !== "simulacion" && MODO !== "produccion") throw new Error("modo desconocido");
if (!idOk(CALENDARIO)) {
  throw new Error("ID de calendario no permitido");
}
const hoy = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Madrid" }).format(new Date());
return [{ json: {
  modo: MODO,
  cuenta: CUENTA,
  calendario: CALENDARIO,
  max_proyectos_simultaneos: 1,
  plazo_minimo_dias_laborables: 3,
  semanas_visibles: 4,
  hoy,
  proyectos: [],
  bloqueos: [],
  secreto_configurado: SECRET !== "REEMPLAZAR_EN_N8N",
  url_publicacion: URL_PUBLICACION
} }];

const item = $input.first().json;
item.proyectos = [];
item.bloqueos = [];
return [{ json: item }];

// Clasifica los eventos del calendario de info@sobtree.com y los convierte en rangos de fechas [inicio, fin).
// Un solo calendario: solo cuentan dos tipos de evento y el resto (reuniones, citas, recordatorios) se ignora.
//   · PROYECTO: lo crea Contrata. Título que empieza por «CONTRATA ·» o propiedad extendida privada sobtree_contrata = 1.
//   · BLOQUEO: lo pones tú a mano. Título que empieza por «BLOQUEO» (p. ej. «BLOQUEO · vacaciones»).
// Los bloqueos solo aportan fechas (nunca títulos ni descripciones). Los proyectos aportan además el id de sesión de Stripe
// (de la descripción del evento) para no contar dos veces una plaza ya reservada en el calendario.
const cfg = $("Configuración").first().json;
const sumar = (iso, n) => { const d = new Date(iso + "T00:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const eventos = $("Google · Calendario").all().map((i) => i.json).filter((e) => e && e.start && e.end && e.status !== "cancelled");
const esProyecto = (e) => /^\s*CONTRATA\s*·/i.test(String(e.summary || "")) || String(((e.extendedProperties || {}).private || {}).sobtree_contrata || "") === "1";
const esBloqueo = (e) => !esProyecto(e) && /^\s*BLOQUEO(?![A-Za-zÁÉÍÓÚáéíóúÑñ])/i.test(String(e.summary || ""));
const rango = (e) => {
  const ini = e.start.date || String(e.start.dateTime).slice(0, 10);
  let fin;
  if (e.end.date) fin = e.end.date;
  else {
    const f = String(e.end.dateTime);
    fin = f.slice(0, 10);
    if (!/T00:00:00/.test(f.slice(10, 19))) fin = sumar(fin, 1);
  }
  if (fin <= ini) fin = sumar(ini, 1);
  return { inicio: ini, fin };
};
const proyectos = eventos.filter(esProyecto).map((e) => {
  const m = String(e.description || "").match(/cs_(?:test|live)_[A-Za-z0-9]+/);
  return { ...rango(e), ...(m ? { sesion: m[0] } : {}) };
});
const bloqueos = eventos.filter(esBloqueo).map((e) => rango(e));
return [{ json: { ...cfg, proyectos, bloqueos, eventos_ignorados: eventos.length - proyectos.length - bloqueos.length } }];

// Lógica compartida del botón «Contrata» (importes, textos honestos y estado del botón).
// La usa el front y las pruebas. No inventa plazas: solo acepta textos que ya cuadran
// con la fórmula publicada por el servidor.

// /condiciones/ es un marcador hasta que Nexus entregue el texto aprobado. Mientras valga true: noindex, fuera del sitemap y sin enlaces públicos.
const CONDICIONES_ES_MARCADOR = true;
const IVA_PORCIENTO = 21;
const RETENCION_MINUTOS = 30;
const SEMANAS_VISIBLES = 4;
const PLAZO_MINIMO_DIAS_LABORABLES = 3;
const MAX_PROYECTOS_SIMULTANEOS = 1;

const TEXTO_RESERVA =
  "Reserva tu diagnóstico; te confirmamos la fecha en 1 día laborable";

const MESES = [
  "enero", "febrero", "marzo", "abril", "mayo", "junio",
  "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"
];

function importes(precioBaseEur, ivaPorciento = IVA_PORCIENTO) {
  const base = Number(precioBaseEur);
  if (!Number.isInteger(base) || base < 0) throw new Error("precio");
  const baseCentimos = base * 100;
  const ivaCentimos = Math.trunc((baseCentimos * ivaPorciento) / 100);
  const totalCentimos = baseCentimos + ivaCentimos;
  return { baseEur: base, ivaPorciento, baseCentimos, ivaCentimos, totalCentimos };
}

function euros(centimos) {
  const signo = centimos < 0 ? "-" : "";
  const abs = Math.abs(centimos);
  const entero = Math.trunc(abs / 100);
  const dec = String(abs % 100).padStart(2, "0");
  return `${signo}${entero.toLocaleString("es-ES")},${dec} €`;
}

function diaSemana(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  const wd = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  return wd === 0 ? 7 : wd;
}

function sumarDias(iso, n) {
  const [y, m, d] = iso.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + n);
  return dt.toISOString().slice(0, 10);
}

function esLaborable(iso) {
  return diaSemana(iso) <= 5;
}

function sumarLaborables(iso, n) {
  let d = iso;
  let rest = n;
  while (rest > 0) {
    d = sumarDias(d, 1);
    if (esLaborable(d)) rest -= 1;
  }
  return d;
}

function siguienteLunes(iso) {
  const n = diaSemana(iso);
  if (n === 1) return iso;
  return sumarDias(iso, 8 - n);
}

function primerLunes(hoy, plazo = PLAZO_MINIMO_DIAS_LABORABLES) {
  return siguienteLunes(sumarLaborables(hoy, plazo));
}

function solapa(aIni, aFin, bIni, bFin) {
  return aIni < bFin && aFin > bIni;
}

function fechaLarga(iso, anoReferencia) {
  const [y, m, d] = iso.split("-").map(Number);
  let txt = `${d} de ${MESES[m - 1]}`;
  if (anoReferencia && y !== anoReferencia) txt += ` de ${y}`;
  return txt;
}

function textoPlazas(n, lunes, max, anoReferencia) {
  if (!Number.isInteger(n) || n < 1 || n > max) return null;
  const fecha = fechaLarga(lunes, anoReferencia);
  if (n === 1) return `Queda 1 plaza para la semana del ${fecha}`;
  return `Quedan ${n} plazas para la semana del ${fecha}`;
}

function textoProxima(lunes, anoReferencia) {
  return `Nuestros agentes pueden empezar a partir del lunes ${fechaLarga(lunes, anoReferencia)}`;
}

function calcularSemanas({ hoy, max, plazo, visibles, proyectos, bloqueos }) {
  const primero = primerLunes(hoy, plazo);
  const ano = Number(hoy.slice(0, 4));
  const semanas = [];
  for (let i = 0; i < visibles; i += 1) {
    const lunes = sumarDias(primero, i * 7);
    const fin = sumarDias(lunes, 5);
    const eventos = (proyectos || []).filter((p) => solapa(p.inicio, p.fin, lunes, fin));
    const bloqueada = (bloqueos || []).some((b) => solapa(b.inicio, b.fin, lunes, fin));
    const plazas = bloqueada ? 0 : Math.max(0, max - eventos.length);
    semanas.push({
      lunes,
      plazas,
      bloqueada,
      proyectos: eventos.length,
      sesiones: eventos.map((e) => e.sesion).filter(Boolean)
    });
  }
  return { hoy, ano, primero, semanas, max };
}

const RE_PLAZA_1 = /^Queda 1 plaza para la semana del \d{1,2} de [a-záéíóúñ]+( de \d{4})?$/;
const RE_PLAZAS_N = /^Quedan [2-9]\d* plazas para la semana del \d{1,2} de [a-záéíóúñ]+( de \d{4})?$/;
const RE_PROXIMA = /^Nuestros agentes pueden empezar a partir del lunes \d{1,2} de [a-záéíóúñ]+( de \d{4})?$/;
const TEXTO_SIN_PLAZAS = "No hay plazas en las próximas 4 semanas.";

function notaPermitida(s) {
  if (typeof s !== "string" || s.length > 180 || /[<>]/.test(s)) return null;
  if (s === TEXTO_SIN_PLAZAS) return s;
  if (RE_PLAZA_1.test(s) || RE_PLAZAS_N.test(s) || RE_PROXIMA.test(s)) return s;
  return null;
}

function estadoBoton(disp) {
  const reserva = { href: "/#contacto", texto: TEXTO_RESERVA, nota: null };
  if (!disp || disp.ok !== true) return reserva;
  const notas = [];
  const proxima = notaPermitida(disp.proxima && disp.proxima.texto);
  if (proxima) notas.push(proxima);
  const semana = Array.isArray(disp.semanas)
    ? disp.semanas.find((s) => s && s.libres >= 1)
    : null;
  const plazas = notaPermitida(semana && semana.texto_plazas);
  if (plazas) notas.push(plazas);
  const sin = notaPermitida(disp.sin_plazas_texto);
  if (!semana && sin) notas.push(sin);
  return { href: "/contratar/", texto: "Contrata", nota: notas.join(" ") || null };
}

const item = $input.first().json;
if (item.modo !== "simulacion" && item.modo !== "produccion") throw new Error("modo desconocido");
const idCal = item.calendario;
if (!idCal || idCal === "primary" || /@gmail\.com$/i.test(idCal)) throw new Error("calendario no permitido");
const calc = calcularSemanas({
  hoy: item.hoy,
  max: item.max_proyectos_simultaneos,
  plazo: item.plazo_minimo_dias_laborables,
  visibles: item.semanas_visibles,
  proyectos: item.proyectos || [],
  bloqueos: item.bloqueos || []
});
const cuerpo = {
  generado: new Date().toISOString(),
  max_proyectos_simultaneos: item.max_proyectos_simultaneos,
  semanas: calc.semanas
};
const raw = JSON.stringify(cuerpo);
if (raw.includes("@")) throw new Error("la publicación no puede llevar datos personales");
const SECRET = "REEMPLAZAR_EN_N8N";
const ts = String(Math.floor(Date.now() / 1000));
const firma = SECRET === "REEMPLAZAR_EN_N8N" ? "" : ("sha256=" + require("crypto").createHmac("sha256", SECRET).update(ts + "." + raw).digest("hex"));
const enviar = SECRET !== "REEMPLAZAR_EN_N8N" && item.url_publicacion && !String(item.url_publicacion).includes("ejemplo.invalid");
if (item.modo === "produccion" && !enviar) throw new Error("En producción hay que pegar el secreto (SECRET) y poner la URL real de publicación.");
return [{ json: { ...item, cuerpo, raw, enviar, firma, ts } }];
